head.script:
scwin.trigger4_onclick = function() {
    var tabNm = "테스트",
        tabKey = "test01";
    var tabOptions = {
        label: tabNm,
        closable: true,
        openAction: "select"
    };
    var contentsOptions = {
        frameMode: "iframe",
        src: "tabControl_spaInitCount_WPFF-23_(WSQ-3076)_sub.xml"
    };
    tabControl1.addTab(tabKey, tabOptions, contentsOptions);
    //선택한 tab 활성화.
    tabControl1.setSelectedTabIndex(tabControl1.getTabIndex(tabKey));
};
scwin.onpageunload = function() {};

scwin.checkVal1 = function() {
    return WebSquare.wUnit.getDomById("tabControl1_contents_test01").style.display == "block";
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 23-Feb-2018
    //End unitTest
}
